// Build data/vocabulary.json — the most frequent words across the whole Quran.
// Input: data/quran/*.json (generated by tools/fetch-quran-data.mjs).
// Output: data/vocabulary.json + tools/vocabulary-review.md (table for a human review pass).
// Usage: node tools/build-vocabulary.mjs [--top 150]
import { readFile, readdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const QURAN = path.join(ROOT, 'data', 'quran');

const args = process.argv.slice(2);
const ti = args.indexOf('--top');
const TOP = ti > -1 ? Number(args[ti + 1]) : 150;

// Strip vocalization: harakat, tanwin, sukun, shadda, superscript alef, tatweel,
// alef wasla, and Quranic annotation marks — so inflected forms group together.
const strip = (s) => s.replace(/[\u0610-\u061A\u064B-\u065F\u0670\u0671\u06D6-\u06ED\u0640]/g, '');

const files = (await readdir(QURAN)).filter((f) => /^\d{3}\.json$/.test(f)).sort();
if (files.length !== 114) {
  console.error(`expected 114 surah files in data/quran, found ${files.length} — run the fetch first`);
  process.exit(1);
}

const counts = new Map(); // normalized form -> { count, first: {...} }
let tokens = 0;
for (const f of files) {
  const surah = JSON.parse(await readFile(path.join(QURAN, f), 'utf8'));
  for (const ayah of surah.ayahs) {
    for (const w of ayah.words) {
      const norm = strip(w.ar);
      if (!norm) continue;
      tokens++;
      const rec = counts.get(norm);
      if (rec) rec.count++;
      else {
        counts.set(norm, {
          count: 1,
          first: {
            ar: w.ar, translit: w.translit, gloss: w.gloss, audio: w.audio,
            ref: `${surah.id}:${ayah.n}`,
          },
        });
      }
    }
  }
}

const top = [...counts.entries()].sort((a, b) => b[1].count - a[1].count).slice(0, TOP);
const words = top.map(([norm, rec], i) => ({
  rank: i + 1,
  ar: rec.first.ar,
  ar_norm: norm,
  translit: rec.first.translit,
  gloss: rec.first.gloss,
  count: rec.count,
  ref: rec.first.ref,
  audio: rec.first.audio,
}));

await writeFile(
  path.join(ROOT, 'data', 'vocabulary.json'),
  JSON.stringify({ generated: new Date().toISOString(), count: words.length, total_tokens: tokens, words }, null, 1),
);

const md = [
  '| rank | word | count | translit | gloss | first ref |',
  '|---|---|---|---|---|---|',
  ...words.map((w) => `| ${w.rank} | ${w.ar} | ${w.count} | ${w.translit} | ${w.gloss} | ${w.ref} |`),
];
await writeFile(path.join(ROOT, 'tools', 'vocabulary-review.md'), md.join('\n') + '\n');

console.log(`vocabulary.json written: ${words.length} words (${tokens} tokens scanned)`);
console.log(`review table: tools/vocabulary-review.md`);
